=== FILE: apb_regs.v ===
// apb_regs: APB4 completer with four 32-bit read/write registers.
// Implements microarchitecture.md (zero wait states, no state machine,
// PSLVERR for unmapped addresses) for interface_spec.md.
`default_nettype none

module apb_regs #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

  localparam integer STRB_WIDTH = DATA_WIDTH / 8;

  // ---------------------------------------------------------------------
  // State: the four registers, as separate flops.
  // ---------------------------------------------------------------------
  reg [DATA_WIDTH-1:0] reg0;
  reg [DATA_WIDTH-1:0] reg1;
  reg [DATA_WIDTH-1:0] reg2;
  reg [DATA_WIDTH-1:0] reg3;

  reg [DATA_WIDTH-1:0] reg0_d;
  reg [DATA_WIDTH-1:0] reg1_d;
  reg [DATA_WIDTH-1:0] reg2_d;
  reg [DATA_WIDTH-1:0] reg3_d;

  // ---------------------------------------------------------------------
  // Decode.
  // ---------------------------------------------------------------------
  // The access phase: the one cycle where the transfer completes
  // (pready is always high).
  wire       access = psel & penable;
  // Mapped: word aligned and inside 0x0 .. 0xC.
  wire       mapped = (paddr[1:0] == 2'b00) &&
                      (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
  wire [1:0] idx    = paddr[3:2];
  wire       wr_en  = access & pwrite & mapped;
  wire       rd_en  = access & ~pwrite & mapped;

  // Byte mask from the strobes: lane n covers bits 8n+7:8n.
  wire [DATA_WIDTH-1:0] wmask;
  genvar gi;
  generate
    for (gi = 0; gi < STRB_WIDTH; gi = gi + 1) begin : g_wmask
      assign wmask[8*gi +: 8] = {8{pstrb[gi]}};
    end
  endgenerate

  // ---------------------------------------------------------------------
  // Read multiplexer (also the old value for the byte merge).
  // ---------------------------------------------------------------------
  reg [DATA_WIDTH-1:0] rd_mux;
  always @* begin
    case (idx)
      2'd0:    rd_mux = reg0;
      2'd1:    rd_mux = reg1;
      2'd2:    rd_mux = reg2;
      2'd3:    rd_mux = reg3;
      default: rd_mux = {DATA_WIDTH{1'b0}};
    endcase
  end

  // merge(old, data, strb): strobed bytes from pwdata, other bytes kept.
  wire [DATA_WIDTH-1:0] wr_merged = (rd_mux & ~wmask) | (pwdata & wmask);

  // ---------------------------------------------------------------------
  // Next state.
  // ---------------------------------------------------------------------
  always @* begin
    reg0_d = reg0;
    reg1_d = reg1;
    reg2_d = reg2;
    reg3_d = reg3;
    if (wr_en) begin
      case (idx)
        2'd0:    reg0_d = wr_merged;
        2'd1:    reg1_d = wr_merged;
        2'd2:    reg2_d = wr_merged;
        2'd3:    reg3_d = wr_merged;
        default: reg0_d = reg0;
      endcase
    end
  end

  // ---------------------------------------------------------------------
  // Register block: synchronous, active-low reset to zero.
  // ---------------------------------------------------------------------
  always @(posedge pclk) begin
    if (!presetn) begin
      reg0 <= {DATA_WIDTH{1'b0}};
      reg1 <= {DATA_WIDTH{1'b0}};
      reg2 <= {DATA_WIDTH{1'b0}};
      reg3 <= {DATA_WIDTH{1'b0}};
    end else begin
      reg0 <= reg0_d;
      reg1 <= reg1_d;
      reg2 <= reg2_d;
      reg3 <= reg3_d;
    end
  end

  // ---------------------------------------------------------------------
  // Responses.
  // ---------------------------------------------------------------------
  assign pready  = 1'b1;
  assign pslverr = access & ~mapped;
  assign prdata  = rd_en ? rd_mux : {DATA_WIDTH{1'b0}};

`ifdef FORMAL
  // Design-intent properties (microarchitecture.md section 6). The decode
  // and byte checks below are written independently of mapped/wr_merged.
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge pclk) f_past_valid <= 1'b1;

  wire f_access = psel && penable;
  wire f_mapped = (paddr < 16) && (paddr[1:0] == 2'b00);

  // Manager assumptions.
  always @(*) begin
    if (!f_past_valid) assume(!presetn);
    if (!presetn)      assume(!psel);
    if (!psel)         assume(!penable);
  end

  always @(posedge pclk) begin
    if (f_past_valid) begin
      // Access only directly after setup.
      if (psel && penable)
        assume($past(psel) && !$past(penable) && $past(presetn));
      // Setup is always followed by access.
      if ($past(presetn) && presetn && $past(psel) && !$past(penable))
        assume(psel && penable);
      // Request stable from setup into access.
      if (psel && penable)
        assume((paddr == $past(paddr)) && (pwrite == $past(pwrite)) &&
               (pwdata == $past(pwdata)) && (pstrb == $past(pstrb)));
    end
  end

  // Independent read model.
  reg [DATA_WIDTH-1:0] f_sel;
  always @(*) begin
    if (paddr == 0)       f_sel = reg0;
    else if (paddr == 4)  f_sel = reg1;
    else if (paddr == 8)  f_sel = reg2;
    else if (paddr == 12) f_sel = reg3;
    else                  f_sel = {DATA_WIDTH{1'b0}};
  end

  // Response rules.
  always @(*) begin
    assert(pready);
    if (!f_access) begin
      assert(prdata == {DATA_WIDTH{1'b0}});
      assert(!pslverr);
    end else begin
      assert(pslverr == !f_mapped);
      if (!pwrite) assert(prdata == f_sel);
    end
  end

  // Registers are zero after reset.
  always @(posedge pclk) begin
    if (f_past_valid && !$past(presetn)) begin
      assert(reg0 == {DATA_WIDTH{1'b0}});
      assert(reg1 == {DATA_WIDTH{1'b0}});
      assert(reg2 == {DATA_WIDTH{1'b0}});
      assert(reg3 == {DATA_WIDTH{1'b0}});
    end
  end

  // Each byte changes only in a mapped write access to its register with
  // its strobe set, and then to the written byte.
  genvar fb;
  generate
    for (fb = 0; fb < STRB_WIDTH; fb = fb + 1) begin : g_fbyte
      always @(posedge pclk) begin
        if (f_past_valid && $past(presetn)) begin
          if ($past(f_access && pwrite && pstrb[fb] && (paddr == 0)))
            assert(reg0[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
          else
            assert(reg0[8*fb +: 8] == $past(reg0[8*fb +: 8]));
          if ($past(f_access && pwrite && pstrb[fb] && (paddr == 4)))
            assert(reg1[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
          else
            assert(reg1[8*fb +: 8] == $past(reg1[8*fb +: 8]));
          if ($past(f_access && pwrite && pstrb[fb] && (paddr == 8)))
            assert(reg2[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
          else
            assert(reg2[8*fb +: 8] == $past(reg2[8*fb +: 8]));
          if ($past(f_access && pwrite && pstrb[fb] && (paddr == 12)))
            assert(reg3[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
          else
            assert(reg3[8*fb +: 8] == $past(reg3[8*fb +: 8]));
        end
      end
    end
  endgenerate

  // Covers: a mapped read returning nonzero data, an error response.
  always @(*) begin
    cover(f_access && !pwrite && f_mapped && (prdata != {DATA_WIDTH{1'b0}}));
    cover(f_access && pslverr);
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_regs_tb.v ===
// apb_regs_tb: directed self-checking testbench for apb_regs.
// Drives inputs after the falling edge, samples 1 time unit later
// (before the rising edge). Expected values come from a testbench model.
`default_nettype none

module apb_regs_tb;

  reg         pclk;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  wire [31:0] prdata;
  wire        pready;
  wire        pslverr;

  integer passed;
  integer failed;
  integer phase;
  integer rc;
  integer r;
  integer s;
  integer k;
  reg [8*64-1:0] nonce;
  reg [31:0]     model [0:3];

  apb_regs #(
      .ADDR_WIDTH(8),
      .DATA_WIDTH(32)
  ) dut (
      .pclk   (pclk),
      .presetn(presetn),
      .paddr  (paddr),
      .psel   (psel),
      .penable(penable),
      .pwrite (pwrite),
      .pwdata (pwdata),
      .pstrb  (pstrb),
      .prdata (prdata),
      .pready (pready),
      .pslverr(pslverr)
  );

  initial pclk = 1'b0;
  always #5 pclk = ~pclk;

  // ---------------------------------------------------------------
  // Reference model helpers (independent of the RTL).
  // ---------------------------------------------------------------
  function tb_mapped(input [7:0] a);
    tb_mapped = (a[1:0] == 2'b00) && (a < 8'h10);
  endfunction

  function [31:0] tb_merge(input [31:0] old, input [31:0] data, input [3:0] strb);
    begin
      tb_merge = old;
      if (strb[0]) tb_merge[7:0]   = data[7:0];
      if (strb[1]) tb_merge[15:8]  = data[15:8];
      if (strb[2]) tb_merge[23:16] = data[23:16];
      if (strb[3]) tb_merge[31:24] = data[31:24];
    end
  endfunction

  // ---------------------------------------------------------------
  // Checks. Tags: 1/2 setup quiet, 3 pready, 4 pslverr, 5 read data,
  // 6/7 idle quiet, 8/9 reset quiet.
  // ---------------------------------------------------------------
  task check32(input [31:0] got, input [31:0] expd, input integer tag);
    begin
      if (got === expd) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("phase %0d check %0d: got 0x%08h, expected 0x%08h (paddr 0x%02h) at %0t",
               phase, tag, got, expd, paddr, $time);
      end
    end
  endtask

  task check1(input got, input expd, input integer tag);
    begin
      if (got === expd) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("phase %0d check %0d: got %b, expected %b (paddr 0x%02h) at %0t",
               phase, tag, got, expd, paddr, $time);
      end
    end
  endtask

  // ---------------------------------------------------------------
  // Bus tasks.
  // ---------------------------------------------------------------
  task setup_phase(input [7:0] addr, input wr, input [31:0] data, input [3:0] strb);
    begin
      @(negedge pclk);
      psel    = 1'b1;
      penable = 1'b0;
      pwrite  = wr;
      paddr   = addr;
      pwdata  = data;
      pstrb   = strb;
      #1;
      check32(prdata, 32'h0000_0000, 1);
      check1(pslverr, 1'b0, 2);
    end
  endtask

  task access_phase(input exp_err);
    begin
      @(negedge pclk);
      penable = 1'b1;
      #1;
      check1(pready, 1'b1, 3);
      check1(pslverr, exp_err, 4);
    end
  endtask

  task apb_write(input [7:0] addr, input [31:0] data, input [3:0] strb);
    begin
      setup_phase(addr, 1'b1, data, strb);
      access_phase(!tb_mapped(addr));
      if (tb_mapped(addr))
        model[addr[3:2]] = tb_merge(model[addr[3:2]], data, strb);
    end
  endtask

  task apb_read(input [7:0] addr);
    reg [31:0] expd;
    begin
      expd = tb_mapped(addr) ? model[addr[3:2]] : 32'h0000_0000;
      setup_phase(addr, 1'b0, 32'hDEAD_BEEF, 4'h0);
      access_phase(!tb_mapped(addr));
      check32(prdata, expd, 5);
    end
  endtask

  task read_all;
    begin
      apb_read(8'h00);
      apb_read(8'h04);
      apb_read(8'h08);
      apb_read(8'h0C);
    end
  endtask

  // Idle cycles: psel low while write-like signals are driven, which
  // must not write anything; responses must be quiet.
  task idle(input integer n);
    integer j;
    begin
      for (j = 0; j < n; j = j + 1) begin
        @(negedge pclk);
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b1;
        pwdata  = 32'hFFFF_FFFF;
        pstrb   = 4'hF;
        #1;
        check32(prdata, 32'h0000_0000, 6);
        check1(pslverr, 1'b0, 7);
      end
    end
  endtask

  task do_reset(input integer n);
    integer j;
    begin
      for (j = 0; j < n; j = j + 1) begin
        @(negedge pclk);
        presetn = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        #1;
        check32(prdata, 32'h0000_0000, 8);
        check1(pslverr, 1'b0, 9);
      end
      @(negedge pclk);
      presetn = 1'b1;
      #1;
      check32(prdata, 32'h0000_0000, 8);
      check1(pslverr, 1'b0, 9);
      for (j = 0; j < 4; j = j + 1) model[j[1:0]] = 32'h0000_0000;
    end
  endtask

  // ---------------------------------------------------------------
  // Test sequence.
  // ---------------------------------------------------------------
  initial begin
    passed  = 0;
    failed  = 0;
    phase   = 0;
    nonce   = {(8*64){1'b0}};
    rc      = $value$plusargs("nirmaan_nonce=%s", nonce);
    presetn = 1'b0;
    psel    = 1'b0;
    penable = 1'b0;
    pwrite  = 1'b0;
    paddr   = 8'h00;
    pwdata  = 32'h0000_0000;
    pstrb   = 4'h0;
    for (k = 0; k < 4; k = k + 1) model[k[1:0]] = 32'h0000_0000;

    // 1: reset, quiet outputs during reset.
    phase = 1;
    do_reset(4);

    // 2: reset values, back-to-back reads.
    phase = 2;
    read_all;
    idle(2);

    // 3: full-word writes back to back, then readback.
    phase = 3;
    apb_write(8'h00, 32'h0123_4567, 4'hF);
    apb_write(8'h04, 32'h89AB_CDEF, 4'hF);
    apb_write(8'h08, 32'hDEAD_BEEF, 4'hF);
    apb_write(8'h0C, 32'hCAFE_F00D, 4'hF);
    read_all;
    idle(3);

    // 4: write then read each register, with 0..3 idle cycles between.
    phase = 4;
    for (r = 0; r < 4; r = r + 1) begin
      apb_write({4'h0, r[1:0], 2'b00}, ~(32'h1111_1111 * (r + 1)), 4'hF);
      apb_read({4'h0, r[1:0], 2'b00});
      idle(r);
    end
    read_all;

    // 5: every strobe pattern (including none) on every register.
    phase = 5;
    for (r = 0; r < 4; r = r + 1) begin
      for (s = 0; s < 16; s = s + 1) begin
        apb_write({4'h0, r[1:0], 2'b00}, 32'h9E37_79B9 * (s + 1 + 16 * r), s[3:0]);
        apb_read({4'h0, r[1:0], 2'b00});
      end
      read_all;
      idle(1);
    end

    // 6: unmapped writes at every unmapped address must change nothing.
    phase = 6;
    for (k = 0; k < 256; k = k + 1) begin
      if (tb_mapped(k[7:0]) == 1'b0)
        apb_write(k[7:0], 32'hFFFF_FFFF ^ k, 4'hF);
    end
    apb_write(8'h10, 32'h5555_5555, 4'h0);
    apb_write(8'h05, 32'hAAAA_AAAA, 4'h0);
    read_all;
    idle(2);

    // 7: read every address in the slot: mapped data or zero with PSLVERR.
    phase = 7;
    for (k = 0; k < 256; k = k + 1) begin
      apb_read(k[7:0]);
    end
    idle(1);
    read_all;

    // 8: reset again after traffic.
    phase = 8;
    apb_write(8'h00, 32'hA1A2_A3A4, 4'hF);
    apb_write(8'h04, 32'hB1B2_B3B4, 4'hF);
    apb_write(8'h08, 32'hC1C2_C3C4, 4'hF);
    apb_write(8'h0C, 32'hD1D2_D3D4, 4'hF);
    read_all;
    do_reset(3);
    read_all;

    // 9: traffic after reset, back to back.
    phase = 9;
    apb_write(8'h0C, 32'h1357_9BDF, 4'hF);
    apb_write(8'h00, 32'h2468_ACE0, 4'h5);
    apb_read(8'h0C);
    apb_read(8'h00);
    apb_write(8'h08, 32'hFEDC_BA98, 4'hA);
    apb_read(8'h08);
    apb_read(8'h04);
    idle(2);

    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule

`default_nettype wire
=== END FILE ===
